const D = { energy: .55, scale: 1, density: .55, speed: 1, crevasse: .6, brash: .5, hue: 196, x: .45, y: .74, style: 'terminus', act: 'creep', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 196;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NF = 3;                                    // ice faces, 0 = farthest

// ---------------- styles ----------------
const STY = {
  // the calving face on an overcast day — cold white ice, englacial blue, black water
  terminus:     { skyT:[206,20,52], skyL:[200,10,74], iceH:[196,10,84], iceL:[200,26,54], blue:[200,66,54],
                  crev:[204,74,34], wat:[204,40,17], moraine:[32,18,30], spray:[198,6,92], fringe:0, nacre:0, grain:22 },
  // blue hour — the ice is the only thing left with light in it
  bluehour:     { skyT:[240,62,20], skyL:[216,40,42], iceH:[204,22,66], iceL:[212,42,40], blue:[210,74,48],
                  crev:[218,80,26], wat:[222,52,12], moraine:[228,26,16], spray:[204,12,74], fringe:0, nacre:0, grain:18 },
  // a filthy ablating terminus — sediment banding, ochre, the ice losing
  moraine:      { skyT:[38,14,50], skyL:[36,10,70], iceH:[38,10,68], iceL:[32,26,42], blue:[192,44,44],
                  crev:[28,44,26], wat:[34,30,18], moraine:[26,34,24], spray:[38,8,80], fringe:0, nacre:0, grain:32 },
  // ABSTRACTED: an InSAR interferogram — rainbow fringes encode surface velocity, not light
  interferogram:{ skyT:[240,30,10], skyL:[240,22,14], iceH:[0,70,80], iceL:[0,70,80], blue:[0,70,80],
                  crev:[240,20,18], wat:[240,26,14], moraine:[240,18,20], spray:[0,0,96], fringe:1, nacre:0, grain:4 },
  // ABSTRACTED: iridescent — the face rendered as a thin-film oil-slick shell, no ice colour at all
  nacre:        { skyT:[268,44,18], skyL:[280,26,34], iceH:[300,40,70], iceL:[190,50,52], blue:[160,60,64],
                  crev:[268,54,28], wat:[258,40,16], moraine:[286,28,24], spray:[300,20,88], fringe:0, nacre:1, grain:8 }
};
const st = STY[P.style] || STY.terminus;

const en = Math.max(0, Math.min(1, P.energy));
const cv = Math.max(0, Math.min(1, P.crevasse));
const wy = height * P.y;                          // the waterline at the foot of the face
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.crevasse.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.fc.forEach(f => f.g.remove()); S.mist.remove(); }
  S.sky = mk(W, H); S.mist = mk(W, Math.max(2, wy + u * .08));

  const g = S.sky; g.noStroke();
  const cT = sh(st.skyT), cL = sh(st.skyL);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cL, Math.pow(Math.min(1, yy / Math.max(1, wy)), .8)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const iceH = sh(st.iceH), iceL = sh(st.iceL), blueC = sh(st.blue), crevC = sh(st.crev), morC = sh(st.moraine);

  // --- the faces: nearer ones stand taller, whiter and further forward ---
  S.fc = [];
  S.calve = [];
  for (let L = 0; L < NF; L++) {
    const near = L / (NF - 1);
    const haze = (1 - near) * (.42 + .3 * (1 - cv));
    const topY = wy - u * (.16 + near * .34) * P.scale;
    const bh = Math.max(4, Math.ceil(wy - topY + u * .06));
    const q = mk(W, bh);
    const base = L3(L3(iceL, iceH, .3 + near * .6), L3(sh(st.skyL), iceH, .5), haze);
    const bl = L3(blueC, L3(sh(st.skyL), iceH, .5), haze * .8);
    const cr = L3(crevC, L3(sh(st.skyL), iceH, .5), haze * .7);

    // the crest: a sawtooth of seracs, never a level parapet
    const crest = xx => {
      const n = Math.abs(Math.sin(xx * .0061 + fr(L * 7 + 1) * 6.3)) * .5
              + Math.abs(Math.sin(xx * .019 + fr(L * 7 + 2) * 6.3)) * .3
              + Math.abs(Math.sin(xx * .041 + fr(L * 7 + 3) * 6.3)) * .2;
      return u * (.03 + .05 * near) * P.scale * (1 - n) + u * .01;
    };
    if (st.fringe) {
      // interferogram: a field of velocity fringes — colour wraps, it does not shade.
      // Computed into a coarse buffer and upscaled: fringes are smooth, so the interpolation
      // costs nothing and this stays ~10k cells instead of ~100k.
      const CW = 200, CH = Math.max(2, Math.ceil(CW * bh / W));
      const fg = mk(CW, CH); fg.noStroke();
      for (let ix = 0; ix < CW; ix++) {
        const xx = ix * W / CW;
        const cy = crest(xx) * CH / bh;
        for (let iy = Math.floor(cy); iy < CH; iy++) {
          const d = (iy - cy) / Math.max(1, CH - cy);
          // range change is fastest at the terminus, so the fringes crowd toward it
          const phi = (Math.pow(1 - d, 1.7) * (7 + cv * 12) + Math.sin(xx * .004 + fr(L) * 6.3) * 1.4 + near * 2) % 1;
          fg.fill(hw(phi * 360 + ho), 62 + 24 * (1 - haze), 62 + 26 * (1 - d));
          fg.rect(ix, iy, 1.2, 1.2);
        }
      }
      q.image(fg, 0, 0, W, bh); fg.remove();
      S.fc.push({ g: q, y: topY, near: near }); continue;
    }

    // the ice mass
    q.noStroke(); q.fill(base[0], base[1], base[2], 100);
    q.beginShape(); q.vertex(-20, bh + 20);
    for (let xx = -20; xx <= W + 20; xx += 6) q.vertex(xx, crest(xx));
    q.vertex(W + 20, bh + 20); q.endShape(q.CLOSE);

    // stratification: annual layers, dipping. This is what makes ice read as ice.
    q.noFill();
    const nst = Math.floor(16 + P.density * 20);
    for (let i = 0; i < nst; i++) {
      const f = i / nst;
      q.strokeWeight(Math.max(.5, u * .0014 * (.3 + near)));
      const sc = st.nacre ? L3(bl, base, f) : L3(base, iceH, .4 + fr(i) * .4);
      const dirty = fr(i * 5 + 11) < .3 ? L3(sc, morC, .5) : sc;
      q.stroke(dirty[0], dirty[1], Math.max(2, dirty[2] + (fr(i * 3) - .5) * 12), 30 + 26 * near);
      q.beginShape();
      for (let xx = -20; xx <= W + 20; xx += 16)
        q.vertex(xx, crest(xx) + u * .02 + f * (bh - u * .04) + Math.sin(xx * .0037 + i * .7) * u * .012 * P.scale);
      q.endShape();
    }
    q.noStroke();

    // crevasses + serac fissures: the blue comes from depth, so they must be modelled, not drawn
    const ncv = Math.floor((6 + P.density * 12) * (.3 + cv));
    for (let i = 0; i < ncv; i++) {
      const cx2 = fr(L * 31 + i * 3 + 21) * W;
      const cy = crest(cx2);
      const cd = (bh - cy) * (.25 + fr(L * 31 + i * 3 + 22) * .7) * (.4 + cv);
      const cw = u * (.006 + fr(L * 31 + i * 3 + 23) * .022) * P.scale * (.4 + cv);
      const lean2 = (fr(i + L) - .5) * .4;
      for (let d = 0; d < 5; d++) {           // walls receding into the fissure -> englacial blue
        const f = d / 4;
        const c = L3(base, st.nacre ? bl : cr, Math.pow(f, .7));
        q.fill(c[0], c[1], Math.max(2, c[2]), 100);
        q.beginShape();
        q.vertex(cx2 - cw * (1 - f * .8) / 2, cy);
        q.vertex(cx2 + cw * (1 - f * .8) / 2, cy);
        q.vertex(cx2 + cw * (1 - f * .8) / 2 + lean2 * cd, cy + cd * (1 - f * .12));
        q.vertex(cx2 - cw * (1 - f * .8) / 2 + lean2 * cd, cy + cd * (1 - f * .12));
        q.endShape(q.CLOSE);
      }
      // the lit lip on the sunward side
      q.noFill(); q.strokeWeight(Math.max(.5, cw * .22));
      q.stroke(iceH[0], iceH[1] * .5, Math.min(99, iceH[2] + 8), (30 + 30 * near) * (P.x > .5 ? 1 : .5));
      q.line(cx2 + cw / 2, cy, cx2 + cw / 2 + lean2 * cd, cy + cd);
      q.noStroke();
      if (near > .6 && S.calve.length < 5) S.calve.push({ x: cx2, y: topY + cy, w: cw * 3, h: cd * .5 });
    }

    // basal sediment: the dirty band where the ice has been grinding rock
    q.fill(morC[0], morC[1], morC[2], 40 + 30 * (P.style === 'moraine' ? 1 : 0));
    q.rect(0, bh - u * (.02 + .03 * near), W, u * (.02 + .03 * near));
    // aerial-perspective veil
    q.fill(sh(st.skyL)[0], st.skyL[1] * .6, st.skyL[2], (1 - near) * 30);
    q.rect(0, 0, W, bh);
    S.fc.push({ g: q, y: topY, near: near });
  }

  // katabatic mist rolling off the face — tileable so the scroll never seams
  const mC = L3(sh(st.spray), sh(st.skyL), .3);
  S.mist.noStroke();
  for (let i = 0; i < 8; i++) {
    const bx = fr(i * 5 + 41) * W, by = wy - u * (.02 + fr(i * 5 + 42) * .16);
    const bw = u * (.25 + fr(i * 5 + 43) * .7), bhh = u * (.02 + fr(i * 5 + 44) * .05);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.mist.fill(mC[0], mC[1] * (1 - kk * .1), Math.min(99, mC[2] + kk * 2), 13 * (1 - kk * .2));
      S.mist.ellipse(bx + rep * W, by + kk * bhh * .14, bw * (1 - kk * .13), bhh * (1 - kk * .1));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = { creep: { c: 0, b: 1 }, calve: { c: .3 + sec * .09, b: 1.4 + sec * .06 }, freeze: { c: 0, b: .5 - sec * .04 } };
const act = ACT[P.act] || ACT.creep;
const brash = Math.max(0, Math.min(1.6, P.brash * act.b));

noStroke();
image(S.sky, 0, 0);

// the faces, farthest first
for (let L = 0; L < NF; L++) {
  const f = S.fc[L];
  const dx = Math.sin(K.t * (.017 + L * .0071) + L * 2.1) * u * .0025 * (.3 + f.near);
  image(f.g, dx, f.y + Math.sin(K.t * (.013 + L * .005) + L) * u * .0012);
}

// katabatic mist off the foot of the face
const W2 = S.mist.width;
const mx = ((-K.t * u * .0067 * P.speed % W2) + W2) % W2;
image(S.mist, mx - W2, 0); image(S.mist, mx, 0);

// ---------------- the water: dark, cold, working ----------------
const watC = sh(st.wat), sprayC = sh(st.spray);
fill(watC[0], watC[1], watC[2]); rect(0, wy, width, height - wy);
const nsw = Math.floor(16 + P.density * 18);
noFill();
for (let i = 0; i < nsw; i++) {
  const f = Math.pow((i + .5) / nsw, 1.9);
  const yy = wy + f * (height - wy);
  const d = Math.max(.03, f);
  const ph = K.t * (.29 + d * .5) * P.speed;
  strokeWeight(Math.max(.5, u * .0014 * (.3 + d * 2)));
  stroke(watC[0], watC[1] * .7, Math.min(99, watC[2] + 12 + 14 * d), 26 + 30 * d);
  beginShape();
  for (let xx = -10; xx <= width + 10; xx += Math.max(8, 18 * d)) {
    const w1 = Math.sin(xx * .008 / (1 + d) + ph) * .7 + Math.sin(xx * .021 - ph * 1.43 + i) * .3 + Math.sin(xx * .0033 + K.t * .229) * .5;
    vertex(xx, yy + w1 * u * .006 * d * (.5 + en));
  }
  endShape();
}
noStroke();

// ---------------- brash ice and growlers drifting out from the face ----------------
const iceH2 = sh(st.iceH), blueC2 = sh(st.blue);
const nb = Math.floor(10 + P.density * 30 * brash);
for (let i = 0; i < nb; i++) {
  // a continuous linear drift with wrap: the reliable motion floor, and it reads as current
  const life = ((K.t * (.012 + fr(i * 3 + 51) * .022) * P.speed + fr(i * 3 + 52)) % 1);
  const f = .04 + life * .95;
  const yy = wy + Math.pow(f, 1.7) * (height - wy);
  const d = Math.max(.05, Math.pow(f, 1.7));
  const bx = (fr(i * 3 + 53) * width + Math.sin(K.t * .05 + i) * u * .03 + (life - .5) * u * .10 * (fr(i) - .5) * 4 + width * 2) % width;
  const bob = Math.sin(K.t * (.7 + i * .13) + i) * u * .0016 * (.3 + d);
  const bw = u * (.008 + fr(i * 3 + 54) * .028) * (.25 + d * 1.8) * P.scale;
  if (st.fringe) { fill(hw(life * 360 + ho), 60, 80, 70); ellipse(bx, yy + bob, bw, bw * .4); continue; }
  fill(iceH2[0], iceH2[1] * .6, Math.min(99, iceH2[2]), 88);
  ellipse(bx, yy + bob, bw, bw * (.32 + fr(i) * .2));
  fill(blueC2[0], blueC2[1] * .8, blueC2[2], 44);      // the waterline shadow under each floe
  ellipse(bx, yy + bob + bw * .1, bw * .8, bw * .12);
}

// ---------------- calving: blocks shearing off. Partial-frame, never a full-frame flash. ----------------
if (act.c > 0 && S.calve && S.calve.length) {
  for (let i = 0; i < S.calve.length; i++) {
    const c = S.calve[i];
    const life = ((K.t * (.035 + fr(i * 5 + 61) * .02) * P.speed + fr(i * 5 + 62)) % 1);
    if (life > act.c) continue;
    const fall = life / Math.max(.02, act.c);
    const drop = Math.pow(fall, 2) * (wy - c.y) * .9;
    push();
    translate(c.x, c.y + drop);
    rotate(fall * .5 * (fr(i) - .5) * 2);
    fill(iceH2[0], iceH2[1] * .7, iceH2[2], 90 * (1 - Math.pow(fall, 3)));
    rect(-c.w / 2, 0, c.w, c.h);
    fill(blueC2[0], blueC2[1], blueC2[2], 50 * (1 - Math.pow(fall, 3)));
    rect(-c.w / 2, c.h * .5, c.w, c.h * .5);
    pop();
    if (fall > .8) {   // the splash, and its concussion ring
      const sf = (fall - .8) / .2;
      noFill(); strokeWeight(Math.max(.6, u * .0016 * (1 - sf)));
      stroke(sprayC[0], sprayC[1], sprayC[2], 50 * (1 - sf) * (.4 + .6 * en));
      ellipse(c.x, wy, sf * u * .3, sf * u * .07);
      noStroke();
      for (let j = 0; j < 6; j++) {
        fill(sprayC[0], sprayC[1] * .5, sprayC[2], 40 * (1 - sf));
        ellipse(c.x + (fr(i * 7 + j) - .5) * u * .12 * sf, wy - Math.sin(sf * 3.14) * u * .06 * fr(j + 3), u * .02 * (1 - sf * .5), u * .02 * (1 - sf * .5));
      }
    }
  }
}

// ---------------- the light: flat and cold, or the last of the blue hour ----------------
if (!st.fringe) {
  blendMode(ADD);
  const gx2 = width * P.x + Math.sin(K.t * .0093) * width * .05;
  const gg = (.25 + .75 * en) * (.8 + .2 * K.swell) + A.lowmid * .16;
  for (let i = 3; i >= 0; i--) {
    fill(sprayC[0], st.spray[1] * .5, st.spray[2], (2 + 5 * gg) * (1 - i * .17));
    ellipse(gx2, wy - u * (.1 + i * .12), u * (.4 + i * .5), u * (.14 + i * .2));
  }
  blendMode(BLEND);
}

if (st.grain > 6) {
  const ng = Math.floor(st.grain * 6);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 701) * width) + Math.sin(K.t * .012 + i) * u * .003 + width) % width;
    const gy = fr(i * 3 + 702) * height;
    fill(hw(st.wat[0] + ho), st.wat[1] * .5, fr(i * 3 + 703) > .5 ? 95 : 5, 3 + fr(i) * 6);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .055);
  stroke(hw(st.wat[0] + ho), st.wat[1], st.fringe ? 4 : 7, 18 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();

if (P.alpha < 1) { fill(hw(st.wat[0] + ho), st.wat[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
